//! 🌱️ Bootstrap debt stays with its exact issuer origin until real header return and first Source transition.
use super::*;
use super::super::{GuestLedger,GuestUsage,GuestSettlement,GuestHold};
use semio_plugin_guest_contract::original_actor_context::{OriginalActorBootstrapCall,OriginalActorBootstrapTransitionCall,OriginalBootstrapEffects};
use semio_plugin_host_guest_runtime::{GuestBootstrapHeaderIdentity,GuestBootstrapHeaderDeallocateReturned,GuestFrozenBootstrapBorrow,GuestFrozenEscrowBorrow};
struct Capture{identity:Option<GuestBootstrapHeaderIdentity>,descriptor:Option<GuestRelayGuestSubloan>,bytes:[u8;304],cursor:usize,call:Option<OriginalActorBootstrapCall>,settled:bool}
impl Capture{const fn empty()->Self{Self{identity:None,descriptor:None,bytes:[0;304],cursor:0,call:None,settled:false}}fn terminal_is_empty(&self)->bool{self.identity.is_none()&&self.descriptor.is_none()&&self.cursor==0&&self.call.is_none()&&!self.settled}}
struct Hold{identity:GuestBootstrapHeaderIdentity,producer:OriginalNativeRecipientIdentity,sequence:u64,origin:usize,currency:GuestUsage,returned:Option<GuestBootstrapHeaderDeallocateReturned>}
pub(super) struct BootstrapHistory{capture:Capture,hold:Option<Hold>}
impl BootstrapHistory{pub(super) const fn empty()->Self{Self{capture:Capture::empty(),hold:None}}pub(super) fn pending(&self)->bool{!self.capture.terminal_is_empty()||self.hold.is_some()}pub(super) fn captured(&self)->bool{!self.capture.terminal_is_empty()}pub(super) fn producer(&self)->Option<OriginalNativeRecipientIdentity>{self.hold.as_ref().map(|h|h.producer).or_else(||self.capture.descriptor.map(|d|d.producer))}}
fn pay(cx:&mut StepContext<'_>,items:usize,bytes:usize,work:u64)->Result<bool,OriginalTurnFailure>{let g=cx.retained_grant();if(if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.should_yield()||cx.is_cancelled()})||g.maximum_items<items||g.maximum_copy_bytes<bytes||g.maximum_depth==0||cx.fuel_remaining()<work{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:items,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(work);Ok(true)}
fn same(a:GuestRelayGuestSubloan,b:GuestRelayGuestSubloan)->bool{a.serial==b.serial&&a.purpose==b.purpose&&a.budget==b.budget&&a.producer==b.producer}
fn usage(e:OriginalBootstrapEffects)->GuestUsage{GuestUsage::actual(e.progress,e.work)}
fn axes(v:GuestUsage)->[u64;3]{[v.items as u64,v.copy as u64,v.work]}
fn receipt_fields(v:GuestUsage)->[u64;5]{[v.items as u64,v.copy as u64,v.capacity as u64,v.release as u64,v.work]}
fn hold(ledger:&GuestLedger,descriptor:GuestRelayGuestSubloan,producer:OriginalNativeRecipientIdentity)->Result<(),ValueError>{if descriptor.purpose!=GuestRelayGuestPurpose::Infrastructure||descriptor.producer!=producer||ledger.hold.is_none_or(|h|h.producer!=producer||!same(h.descriptor,descriptor)){return Err(invalid("bootstrap receipt changed its actual infrastructure issuer"))}Ok(())}
impl GuestIssuedHistoryHome{
 /// 🧾️ Applies only actual frozen SAB1 bytes to the issuer ledger under the same native Source.
 pub(super) fn apply_bootstrap_step(mut history:OriginalNativeBorrowed<'_,Self>,frozen:&GuestFrozenBootstrapBorrow<'_>,descriptor:GuestRelayGuestSubloan,ledger:&mut GuestLedger,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  history.validate_context(cx)?;frozen.validate_context(cx)?;let home=history.value_mut();home.validate(cx)?;if home.book.producer().is_some()||home.capture.words.identity.is_some()||home.retiring||home.terminal.is_some(){return Err(invalid("bootstrap cannot follow or overlap a Source publication").into())}let producer=frozen.recipient();let capture=&mut home.bootstrap.capture;
  if let Some(identity)=capture.identity{if identity!=frozen.identity()||capture.descriptor.is_none_or(|d|!same(d,descriptor)){return Err(invalid("bootstrap capture changed its actual frozen issuer").into())}if capture.settled{return Ok(true)}}else{hold(ledger,descriptor,producer)?;if !pay(cx,2,size_of::<Option<GuestBootstrapHeaderIdentity>>()+size_of::<Option<GuestRelayGuestSubloan>>(),2)?{return Ok(false)}capture.identity=Some(frozen.identity());capture.descriptor=Some(descriptor);return Ok(false)}
  hold(ledger,descriptor,producer)?;
  if capture.cursor<304{let word=frozen.header_word(capture.cursor).ok_or_else(||invalid("bootstrap frozen word disappeared"))?;if !pay(cx,1,word.len()+size_of::<usize>(),word.len()as u64+1)?{return Ok(false)}capture.bytes[capture.cursor..capture.cursor+word.len()].copy_from_slice(word);capture.cursor+=word.len();return Ok(false)}
  if capture.call.is_none(){let bytes=size_of::<Option<OriginalActorBootstrapCall>>();let g=cx.retained_grant();if(if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.should_yield()||cx.is_cancelled()})||g.maximum_items==0||g.maximum_copy_bytes<bytes||g.maximum_depth==0||cx.fuel_remaining()<38{return Ok(false)}cx.consume_fuel(38);let call=OriginalActorBootstrapCall::read(&capture.bytes)?;call.validate_expected(descriptor.budget())?;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;capture.call=Some(call);return Ok(false)}
  if !history_lookup_depth(cx,&home.entries)?{return Ok(false)}let call=home.bootstrap.capture.call.ok_or_else(||invalid("bootstrap lost its complete original call"))?;let current=home.entries.len().checked_sub(1).ok_or_else(||invalid("bootstrap issuer was not registered"))?;let mut issued=*home.entries.get(current).ok_or_else(||invalid("bootstrap issuer disappeared"))?;if !same(issued.descriptor,descriptor)||issued.producer!=producer||issued.is_settled(){return Err(invalid("bootstrap has no exact unsettled issued origin").into())}
  let previous=home.bootstrap.hold.as_ref();let prepaid=usage(call.prepaid);let mut old=if let Some(previous)=previous{if previous.producer!=producer||previous.origin==current||call.sequence!=previous.sequence.checked_add(1).ok_or_else(||invalid("bootstrap sequence overflow"))?||call.returned_sequence!=previous.sequence||prepaid!=previous.currency||ledger.bootstrap_held!=previous.currency||previous.returned.as_ref().is_none_or(|proof|!proof.proves(&previous.identity,cx)){return Err(invalid("bootstrap prepaid currency lacks its exact actual prior handback").into())}Some((previous.origin,*home.entries.get(previous.origin).ok_or_else(||invalid("bootstrap prior issuer disappeared"))?))}else{if call.sequence!=1||call.returned_sequence!=0||prepaid!=GuestUsage::default()||ledger.bootstrap_held!=GuestUsage::default(){return Err(invalid("bootstrap first receipt invented prior currency").into())}None};
  let fresh=usage(call.fresh()?);let held=usage(call.held);let observed=ledger.accounts[1].observed.add(fresh)?.add(prepaid)?;let actual=usage(call.actual);
  for field in 0..5{GuestEscrowBook::apply_receipt_field(&mut issued,field,receipt_fields(actual)[field],receipt_fields(fresh)[field])?}
  for axis in 0..3{let delta=[axes(held)[axis],0,0];GuestEscrowBook::check_origin_axis(&issued,delta,axes(fresh)[axis],axis)?;GuestEscrowBook::apply_origin_axis(&mut issued,axis,delta)?;if let Some((_,old))=&mut old{let delta=[0,axes(prepaid)[axis],0];GuestEscrowBook::check_origin_axis(old,delta,GuestEscrowBook::recorded_origin_fresh(old,axis)?,axis)?;GuestEscrowBook::apply_origin_axis(old,axis,delta)?;}}
  GuestEscrowBook::finish_receipt(&mut issued);let items=7+usize::from(old.is_some());let bytes=size_of::<IssuedOrigin>()*(1+usize::from(old.is_some()))+2*size_of::<GuestUsage>()+size_of::<Option<GuestSettlement>>()+size_of::<Option<GuestHold>>()+size_of::<Option<Hold>>()+size_of::<bool>();if !pay(cx,items,bytes,96)?{return Ok(false)}
  *home.entries.get_mut(current).expect("validated current bootstrap issuer")=issued;if let Some((index,old))=old{*home.entries.get_mut(index).expect("validated prior bootstrap issuer")=old;}ledger.accounts[1].observed=observed;ledger.bootstrap_held=held;ledger.last=Some(GuestSettlement{descriptor,input:descriptor.budget().input,progress:call.actual.progress,work:call.actual.work,producer});ledger.hold=None;home.bootstrap.hold=Some(Hold{identity:frozen.identity(),producer,sequence:call.sequence,origin:current,currency:held,returned:None});home.bootstrap.capture.settled=true;Ok(true)
 }
 /// 📮️ Retains the exact actual bootstrap Deallocate witness before retiring its capture.
 pub fn receive_bootstrap_header_return_step(mut history:OriginalNativeBorrowed<'_,Self>,returned:&mut Option<GuestBootstrapHeaderDeallocateReturned>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{history.validate_context(cx)?;let home=history.value_mut();home.validate(cx)?;let last=home.bootstrap.hold.as_mut().ok_or_else(||invalid("bootstrap handback has no held target"))?;if last.returned.is_some(){return Ok(returned.is_none()&&home.bootstrap.capture.terminal_is_empty())}let capture=&home.bootstrap.capture;if !capture.settled||capture.identity!=Some(last.identity)||returned.as_ref().is_none_or(|proof|!proof.proves(&last.identity,cx)){return Err(invalid("bootstrap handback differs from its actual settled target").into())}let bytes=2*GuestBootstrapHeaderDeallocateReturned::retained_copy_bytes()+size_of::<Capture>();if !pay(cx,3,bytes,3)?{return Ok(false)}last.returned=returned.take();home.bootstrap.capture=Capture::empty();Ok(true)}
 /// 👁️ Lends only the exact bootstrap call whose actual issuer has settled.
 pub fn with_bootstrap_call_step(mut history:OriginalNativeBorrowed<'_,Self>,frozen:&GuestFrozenBootstrapBorrow<'_>,cx:&mut StepContext<'_>,receive:impl FnOnce(&OriginalActorBootstrapCall,GuestBootstrapHeaderIdentity,&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{history.validate_context(cx)?;frozen.validate_context(cx)?;let home=history.value_mut();home.validate(cx)?;let c=&home.bootstrap.capture;if !c.settled||c.identity!=Some(frozen.identity()){return Ok(false)}receive(c.call.as_ref().ok_or_else(||invalid("settled bootstrap call disappeared"))?,frozen.identity(),cx)?;Ok(true)}
 /// 🪢️ Redeems the last SAB hold once before the genuine inner Source receipt may commit.
 pub(super) fn apply_bootstrap_transition_step(mut history:OriginalNativeBorrowed<'_,Self>,frozen:&GuestFrozenEscrowBorrow<'_>,ledger:&mut GuestLedger,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{history.validate_context(cx)?;frozen.validate_context(cx)?;let home=history.value_mut();home.validate(cx)?;if home.capture.words.identity.is_none_or(|i|!i.matches(frozen))||home.capture.words.header_length!=200||home.capture.words.header_validation.phase!=6||home.capture.words.validation.phase!=5{return Err(invalid("bootstrap transition lacks its actual validated Source header").into())}if home.capture.bootstrap_transition_accepted{return Ok(true)}if !history_lookup_depth(cx,&home.entries)?{return Ok(false)}let transition=OriginalActorBootstrapTransitionCall::read(&home.capture.words.header[..200])?;let issued=ledger.hold.ok_or_else(||invalid("Source transition lacks its actual current issuer"))?;hold(ledger,issued.descriptor,frozen.recipient())?;if transition.call.input!=issued.descriptor.budget().input||!matches!(frozen.export(),semio_plugin_host_guest_runtime::OwnedSemioExport::AdmitActorContext|semio_plugin_host_guest_runtime::OwnedSemioExport::CloseActorContext){return Err(invalid("Source transition changed its actual current budget or export").into())}let current=home.entries.len().checked_sub(1).and_then(|i|home.entries.get(i)).ok_or_else(||invalid("Source transition current issuer was not registered"))?;if !same(current.descriptor,issued.descriptor)||current.producer!=frozen.recipient()||current.is_settled(){return Err(invalid("Source transition lacks its exact unsettled current origin").into())}let last=home.bootstrap.hold.as_ref().ok_or_else(||invalid("Source transition has no actual prior bootstrap hold"))?;if home.bootstrap.capture.identity.is_some()||last.producer!=frozen.recipient()||last.sequence!=transition.returned.returned_sequence||last.currency!=usage(transition.returned.prepaid)||ledger.bootstrap_held!=last.currency||last.returned.as_ref().is_none_or(|proof|!proof.proves(&last.identity,cx)){return Err(invalid("Source transition changed its actual bootstrap handback or currency").into())}let mut origin=*home.entries.get(last.origin).ok_or_else(||invalid("Source transition lost its actual bootstrap issuer"))?;for axis in 0..3{let delta=[0,axes(last.currency)[axis],0];GuestEscrowBook::check_origin_axis(&origin,delta,GuestEscrowBook::recorded_origin_fresh(&origin,axis)?,axis)?;GuestEscrowBook::apply_origin_axis(&mut origin,axis,delta)?;}let observed=ledger.accounts[1].observed.add(last.currency)?;let index=last.origin;let bytes=size_of::<IssuedOrigin>()+2*size_of::<GuestUsage>()+size_of::<Option<Hold>>()+size_of::<bool>();if !pay(cx,5,bytes,64)?{return Ok(false)}*home.entries.get_mut(index).expect("validated bootstrap transition issuer")=origin;ledger.accounts[1].observed=observed;ledger.bootstrap_held=GuestUsage::default();home.bootstrap.hold=None;home.capture.bootstrap_transition_accepted=true;Ok(true)}
}
